import dataFoundations from 'theme/colors/dataFoundations';

export const PERFORMANCE_TOOL_PAGE_NAME = 'value-creation_performance-tool';

/** Filter drawer field keys (order preserved for grouping within categories). */
export const PERFORMANCE_TOOL_VISIBLE_FILTER_FIELDS: string[] = [
  'zone',
  'country',
  'category',
  'channel',
  'non_alcoholic',
  'brand_filter_groupings',
  'portfolios',
  'beer_price_segment',
  'growth_levers',
  'pack_type',
  'global_brands',
  'brands',
  'sub_brands',
  'sku',
  'periods',
  'time_period',
  'kpis',
];

/**
 * Quick-filter chip order (Figma / MARTLH-13554):
 * Geographic → Category → Channel → Breakdown → SKU → Time Frame → KPI.
 *
 * Legacy `periods` and canonical `time_period` share the same position. The
 * selected KPI exposes only the compatible field.
 */
export const PERFORMANCE_TOOL_QUICK_FILTER_ORDER: string[] = [
  'zone',
  'country',
  'category',
  'channel',
  'growth_levers',
  'non_alcoholic',
  'beer_price_segment',
  'portfolios',
  'pack_type',
  'brand_filter_groupings',
  'global_brands',
  'brands',
  'sub_brands',
  'sku',
  'periods',
  'time_period',
  'kpis',
];

/** Default chips on load: Geographic + Brand + Time Frame + KPI. */
export const PERFORMANCE_TOOL_MAX_VISIBLE_FILTERS = 4;

export const PERFORMANCE_TOOL_NAVIGATION_TEST_ID =
  'performance-tool-navigation';

export { STICKY_NAVIGATION_TOP_OFFSET_FALLBACK_PX as PERFORMANCE_SECTION_STICKY_TOP_OFFSET_FALLBACK_PX } from 'hooks/useStickyNavigationTopOffset/constants';

const { series, waterfall } = dataFoundations.charts.bg;
const { comparison: comparisonStatus } = dataFoundations.charts.txt.status;

export const VALUE_CREATION_LINE_BAR_CHART_COLORS = {
  lastYear: series.lastYear,
  budget: series.budget,
  current: series.current,
};

export const PERFORMANCE_TOOL_VOLUME_LINE_BAR_CHARTS_BFF_ID = `${PERFORMANCE_TOOL_PAGE_NAME}_drill-down_volume_line-bar-charts`;

export const PERFORMANCE_TOOL_VOLUME_CONTRIBUTION_WATERFALL_BFF_ID = `${PERFORMANCE_TOOL_PAGE_NAME}_drill-down_volume_contribution-waterfall`;

export const PERFORMANCE_TOOL_VOLUME_BIG_NUMBERS_BFF_ID = `${PERFORMANCE_TOOL_PAGE_NAME}_drill-down_volume_big-numbers`;

export const PERFORMANCE_TOOL_LINE_BAR_CHARTS_COMPONENT_ID = 'line-bar-charts';

export const PERFORMANCE_TOOL_BIG_NUMBERS_COMPONENT_ID = 'big-numbers';

export const VALUE_CREATION_TREND_COLORS = {
  positive: comparisonStatus.positive,
  negative: comparisonStatus.negative,
  neutral: comparisonStatus.neutral,
};

export const WATERFALL_COLORS = {
  first: waterfall.first,
  last: waterfall.last,
  positive: waterfall.positive,
  negative: waterfall.negative,
};

export const MARKET_SHARE_COUNTRIES_WITHOUT_BRAND_DATA = ['GTM', 'URY', 'ZMB'];

export const PERFORMANCE_TOOL_PATH = '/value-creation/performance-tool';

export const WATERFALL_RESET_EVENT = 'waterfall:filter-reset';

export const PERFORMANCE_TOOL_OPEN_TIME_PERIOD_EVENT =
  'performance-tool:open-time-period';

export const SOURCE_STATUS_VISIBLE_FILTER_FIELDS = ['country', 'periods'];
